/* Selector nativo de foto para artículos dentro de Nueva/Editar orden.
 * iPhone conserva su selector nativo.
 * Android muestra dos opciones explícitas: Cámara o Galería.
 * Reutiliza onFotoFilaItem() original: no cambia persistencia/R2.
 */
if (!window.__smFotoItemNativeFix0906v4) {
  window.__smFotoItemNativeFix0906v4 = true;
  instalarFotoItemNativeFix();
}
const ES_ANDROID = /Android/i.test(navigator.userAgent || '');
function asegurarPreview(row,label){let preview=row.querySelector('.sm-item-native-preview');if(preview)return preview;preview=document.createElement('div');preview.className='sm-item-native-preview';preview.innerHTML='<img alt="Vista previa de la foto"><span>Foto lista para guardar</span>';label.insertAdjacentElement('beforebegin',preview);return preview;}
function mostrarPreview(row,label,file){if(!file)return;const preview=asegurarPreview(row,label);const img=preview.querySelector('img');const anterior=preview.dataset.objectUrl||'';if(anterior){try{URL.revokeObjectURL(anterior);}catch(_){}}const url=URL.createObjectURL(file);preview.dataset.objectUrl=url;img.src=url;preview.style.display='flex';}
function procesarArchivo(row,label,input){const file=input.files&&input.files[0];if(!file)return;row.__smPendingItemPhoto=file;mostrarPreview(row,label,file);if(typeof window.onFotoFilaItem==='function')window.onFotoFilaItem(input);}
function abrirSelectorAndroid(cameraInput,galleryInput){const viejo=document.getElementById('sm-android-photo-choice');if(viejo)viejo.remove();const overlay=document.createElement('div');overlay.id='sm-android-photo-choice';overlay.innerHTML='<div class="sm-android-photo-box"><strong>Agregar foto</strong><button type="button" class="btn btn-primary" data-choice="camera">📷 Sacar foto</button><button type="button" class="btn btn-ghost" data-choice="gallery">🖼️ Elegir de galería</button><button type="button" class="btn btn-ghost" data-choice="cancel">Cancelar</button></div>';overlay.addEventListener('click',e=>{const choice=e.target?.dataset?.choice;if(!choice){if(e.target===overlay)overlay.remove();return;}overlay.remove();if(choice==='camera')cameraInput.click();else if(choice==='gallery')galleryInput.click();});document.body.appendChild(overlay);}
function convertirFila(row){if(!row||row.dataset.smNativePhotoV4==='1')return;const menu=row.querySelector('.sm-item');if(!menu)return;row.dataset.smNativePhotoV4='1';menu.style.display='none';const label=document.createElement(ES_ANDROID?'button':'label');if(ES_ANDROID)label.type='button';label.className='btn btn-ghost btn-sm sm-item-native-label';label.textContent='📷 Agregar foto';label.style.position='relative';label.style.overflow='hidden';label.style.cursor='pointer';const input=document.createElement('input');input.type='file';input.accept='image/*';input.className='sm-item-native-picker';input.removeAttribute('capture');input.style.position='absolute';input.style.inset='0';input.style.width='100%';input.style.height='100%';input.style.opacity='0';input.style.cursor='pointer';input.style.fontSize='100px';input.addEventListener('change',()=>procesarArchivo(row,label,input));if(ES_ANDROID){input.style.display='none';const camera=document.createElement('input');camera.type='file';camera.accept='image/*';camera.setAttribute('capture','environment');camera.className='sm-item-native-camera';camera.style.display='none';camera.addEventListener('change',()=>procesarArchivo(row,label,camera));label.addEventListener('click',()=>abrirSelectorAndroid(camera,input));menu.parentNode.insertBefore(camera,menu.nextSibling);menu.parentNode.insertBefore(input,camera.nextSibling);}else{label.appendChild(input);}menu.parentNode.insertBefore(label,menu.nextSibling);}
function convertirTodas(){document.querySelectorAll('#orden-items-list .articulo-row').forEach(convertirFila);}
function instalarFotoItemNativeFix(){const style=document.createElement('style');style.id='sm-foto-item-native-fix-0906-v4';style.textContent=`#orden-items-list .sm-item{display:none!important}#orden-items-list .sm-item-native-label{display:inline-flex!important;align-items:center;justify-content:center;min-height:44px;touch-action:manipulation;-webkit-tap-highlight-color:transparent}#orden-items-list .sm-item-native-label input[type=file]{display:block!important}#orden-items-list .sm-item-native-preview{display:none;align-items:center;gap:10px;margin:10px 0}#orden-items-list .sm-item-native-preview img{width:86px;height:86px;object-fit:cover;border-radius:10px;border:1px solid var(--line,#ddd)}#orden-items-list .sm-item-native-preview span{font-size:12px;font-weight:700;color:var(--muted,#666)}#sm-android-photo-choice{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.48);display:flex;align-items:flex-end;justify-content:center;padding:18px}.sm-android-photo-box{width:min(440px,100%);background:var(--card,#fff);border-radius:16px;padding:16px;display:grid;gap:10px}.sm-android-photo-box strong{text-align:center;margin-bottom:4px}.sm-android-photo-box button{width:100%;min-height:46px}`;if(!document.getElementById(style.id))document.head.appendChild(style);convertirTodas();const host=document.getElementById('orden-items-list');if(host){const obs=new MutationObserver(()=>convertirTodas());obs.observe(host,{childList:true,subtree:true});}['openOrdenModal','agregarFilaItemOrden','sincronizarCantidadPares'].forEach(nombre=>{const original=window[nombre];if(typeof original!=='function'||original.__smNativePhotoV4)return;const w=function(...args){const r=original.apply(this,args);Promise.resolve(r).finally(()=>requestAnimationFrame(convertirTodas));return r;};w.__smNativePhotoV4=true;window[nombre]=w;});}
